// Generated by the production normalizeImportedContent from Markdown with
// headings, formatting, links, both lists, quote, table, code, formula/divider.
//
//go:embed testdata/local_import_rich.json
var localImportRichBody string

const localImportPlainBody = `{"root":{"type":"root","version":1,"direction":null,"format":"","indent":0,"children":[{"type":"paragraph","version":1,"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","children":[{"type":"text","version":1,"text":"正文 😀 [[literal]]","detail":0,"format":0,"mode":"normal","style":""}]}]}}`

func importCounts(t *testing.T, l *FileLogic, files, receipts, links int) {
	t.Helper()
	for _, table := range []struct {
		name string
		want int
	}{{"files", files}, {"research_note_requests", receipts}, {"links", links}} {
		var count int
		if err := l.FileDAO.DB.QueryRow("SELECT COUNT(*) FROM " + table.name).Scan(&count); err != nil || count != table.want {
			t.Fatalf("%s: got %d want %d; error=%v", table.name, count, table.want, err)
		}
	}
}

func expectImportRejected(t *testing.T, result *LocalImportResult, err error, id, reason string) {
	t.Helper()
	if err != nil || result == nil || result.Status != "rejected" || result.RequestID != id || result.Reason != reason || result.Message == "" || result.Receipt != nil {
		t.Fatalf("expected definite %s rejection: result=%+v err=%v", reason, result, err)
	}
}

func importFolder(t *testing.T, l *FileLogic, id, parent string, folder, deleted int) {
	t.Helper()
	if _, err := l.FileDAO.DB.Exec(`INSERT INTO files(id,title,content,created_at,updated_at,is_folder,parent_id,is_deleted) VALUES(?,?,?,1,1,?,?,?)`, id, "folder-"+id, "", folder, parent, deleted); err != nil {
		t.Fatal(err)
	}
}

func TestLocalImportRichDocumentCommitsContentIndexOrderAndReceipt(t *testing.T) {
	l := researchFixture(t)
	for _, sql := range []string{
		`CREATE VIRTUAL TABLE files_fts USING fts5(title,content,content='files',content_rowid='rowid')`,
		`CREATE TRIGGER files_fts_insert AFTER INSERT ON files BEGIN INSERT INTO files_fts(rowid,title,content) VALUES(new.rowid,new.title,new.content); END`,
	} {
		if _, err := l.FileDAO.DB.Exec(sql); err != nil {
			t.Fatal(err)
		}
	}
	parent := uuid.NewString()
	importFolder(t, l, parent, "", 1, 0)
	if _, err := l.FileDAO.DB.Exec(`INSERT INTO files(id,title,content,created_at,updated_at,parent_id,sort_order) VALUES('sibling','existing.md','',1,1,?,7000)`, parent); err != nil {
		t.Fatal(err)
	}
	id := uuid.NewString()
	result, err := l.CreateLocalImport(context.Background(), id, "完整导入😀.md", localImportRichBody, parent)
	if err != nil || result == nil || result.Status != "committed" || result.Receipt == nil {
		t.Fatalf("rich import failed: %+v %v", result, err)
	}
	r := result.Receipt
	file, err := l.Get(context.Background(), r.FileID)
	if err != nil || file.Content != localImportRichBody || file.Title != "完整导入😀.md" || file.ParentID != parent || file.SortOrder != 8000 {
		t.Fatalf("file/order/content mismatch: %+v %v", file, err)
	}
	hash := sha256.Sum256([]byte("完整导入😀.md\x00" + parent + "\x00" + localImportRichBody))
	if !r.Found || r.State != "available" || r.RequestID != id || r.PayloadSHA256 != hex.EncodeToString(hash[:]) || r.CreatedAt <= 0 {
		t.Fatalf("incorrect receipt: %+v", r)
	}
	var indexed int
	if err := l.FileDAO.DB.QueryRow(`SELECT count(*) FROM files_fts WHERE files_fts MATCH 'total'`).Scan(&indexed); err != nil || indexed != 1 {
		t.Fatalf("committed note was not indexed: %d %v", indexed, err)
	}
	importCounts(t, l, 3, 1, 0)
}

func TestLocalImportLostResponseLookupAndSamePayloadReplay(t *testing.T) {
	l := researchFixture(t)
	id := uuid.NewString()
	// The caller loses the creation response; only the independent receipt
	// lookup is used to recover identity before subsequent same-ID retries.
	if _, err := l.CreateLocalImport(context.Background(), id, "查回.md", localImportPlainBody, ""); err != nil {
		t.Fatal(err)
	}
	receipt, err := l.LocalImportReceipt(context.Background(), id)
	if err != nil || !receipt.Found || receipt.State != "available" {
		t.Fatal(receipt, err)
	}
	for i := 0; i < 4; i++ {
		result, err := l.CreateLocalImport(context.Background(), id, "查回.md", localImportPlainBody, "")
		if err != nil || result.Status != "committed" || *result.Receipt != *receipt {
			t.Fatal(result, err)
		}
	}
	importCounts(t, l, 1, 1, 0)
}

func TestLocalImportReplayNeverRevertsEditsOrResurrectsDeletedNote(t *testing.T) {
	for _, state := range []string{"available", "deleted", "missing"} {
		t.Run(state, func(t *testing.T) {
			l := researchFixture(t)
			id := uuid.NewString()
			first, err := l.CreateLocalImport(context.Background(), id, "原稿.md", localImportPlainBody, "")
			if err != nil {
				t.Fatal(err)
			}
			fileID := first.Receipt.FileID
			query := `UPDATE files SET title='later.md',content='later content' WHERE id=?`
			if state == "deleted" {
				query = `UPDATE files SET is_deleted=1 WHERE id=?`
			} else if state == "missing" {
				query = `DELETE FROM files WHERE id=?`
			}
			if _, err := l.FileDAO.DB.Exec(query, fileID); err != nil {
				t.Fatal(err)
			}
			result, err := l.CreateLocalImport(context.Background(), id, "原稿.md", localImportPlainBody, "")
			if err != nil || result.Status != "committed" || result.Receipt.State != state || result.Receipt.FileID != fileID || result.Receipt.Title != "原稿.md" {
				t.Fatal(result, err)
			}
			if state == "available" {
				file, err := l.Get(context.Background(), fileID)
				if err != nil || file.Content != "later content" || file.Title != "later.md" {
					t.Fatal(file, err)
				}
			}
			files := 1
			if state == "missing" {
				files = 0
			}
			importCounts(t, l, files, 1, 0)
		})
	}
}

func TestLocalImportBoundIdentityRejectsChangedAndInvalidPayloads(t *testing.T) {
	l := researchFixture(t)
	id := uuid.NewString()
	first, err := l.CreateLocalImport(context.Background(), id, "原稿.md", localImportPlainBody, "")
	if err != nil {
		t.Fatal(err)
	}
	for _, args := range [][3]string{
		{"new.md", localImportPlainBody, ""},
		{"原稿.md", localImportPlainBody + " ", ""},
		{"原稿.md", localImportPlainBody, uuid.NewString()},
		{"", "not JSON", ""},
		{"原稿.md", "", ""},
	} {
		result, err := l.CreateLocalImport(context.Background(), id, args[0], args[1], args[2])
		expectImportRejected(t, result, err, id, "payload-mismatch")
	}
	malformed, err := l.RejectLocalImportInput(context.Background(), id, "bad JSON")
	expectImportRejected(t, malformed, err, id, "payload-mismatch")
	file, err := l.Get(context.Background(), first.Receipt.FileID)
	if err != nil || file.Content != localImportPlainBody || file.Title != "原稿.md" {
		t.Fatal(file, err)
	}
	importCounts(t, l, 1, 1, 0)
}

func TestLocalImportUnavailableParentNeverFallsBackOrReservesID(t *testing.T) {
	for _, scenario := range []string{"missing", "deleted", "not-folder", "deleted-ancestor", "missing-ancestor", "cycle"} {
		t.Run(scenario, func(t *testing.T) {
			l := researchFixture(t)
			parent, ancestor := uuid.NewString(), uuid.NewString()
			files := 0
			switch scenario {
			case "deleted":
				importFolder(t, l, parent, "", 1, 1)
				files = 1
			case "not-folder":
				importFolder(t, l, parent, "", 0, 0)
				files = 1
			case "deleted-ancestor":
				importFolder(t, l, parent, ancestor, 1, 0)
				importFolder(t, l, ancestor, "", 1, 1)
				files = 2
			case "missing-ancestor":
				importFolder(t, l, parent, ancestor, 1, 0)
				files = 1
			case "cycle":
				importFolder(t, l, parent, ancestor, 1, 0)
				importFolder(t, l, ancestor, parent, 1, 0)
				files = 2
			}
			id := uuid.NewString()
			result, err := l.CreateLocalImport(context.Background(), id, "导入.md", localImportPlainBody, parent)
			expectImportRejected(t, result, err, id, "folder-unavailable")
			importCounts(t, l, files, 0, 0)
		})
	}
}

func TestLocalImportCaseInsensitiveConflictIsRepairableWithoutOverwrite(t *testing.T) {
	for _, folder := range []int{0, 1} {
		t.Run(fmt.Sprint(folder), func(t *testing.T) {
			l := researchFixture(t)
			if _, err := l.FileDAO.DB.Exec(`INSERT INTO files(id,title,content,created_at,updated_at,is_folder) VALUES('existing','Draft.MD','original',1,1,?)`, folder); err != nil {
				t.Fatal(err)
			}
			id := uuid.NewString()
			result, err := l.CreateLocalImport(context.Background(), id, "draft.md", localImportPlainBody, "")
			expectImportRejected(t, result, err, id, "name-conflict")
			importCounts(t, l, 1, 0, 0)
			result, err = l.CreateLocalImport(context.Background(), id, "different.md", localImportPlainBody, "")
			if err != nil || result.Status != "committed" {
				t.Fatal(result, err)
			}
			var content string
			if err := l.FileDAO.DB.QueryRow(`SELECT content FROM files WHERE id='existing'`).Scan(&content); err != nil || content != "original" {
				t.Fatal(content, err)
			}
			importCounts(t, l, 2, 1, 0)
		})
	}
}

func TestLocalImportPreflightRejectsWithoutWriting(t *testing.T) {
	cases := []struct{ name, id, title, body, parent string }{
		{"bad-id", "not-uuid", "导入.md", localImportPlainBody, ""},
		{"uppercase-id", strings.ToUpper(uuid.NewString()), "导入.md", localImportPlainBody, ""},
		{"wrong-variant", "aaaaaaaa-aaaa-4aaa-0aaa-aaaaaaaaaaaa", "导入.md", localImportPlainBody, ""},
		{"empty-title", "", "", localImportPlainBody, ""},
		{"title-spaces", "", " 导入.md", localImportPlainBody, ""},
		{"title-control", "", "导入\x01.md", localImportPlainBody, ""},
		{"title-path", "", "../导入.md", localImportPlainBody, ""},
		{"template-prefix", "", "__tpl__secret", localImportPlainBody, ""},
		{"title-too-long", "", strings.Repeat("😀", 256), localImportPlainBody, ""},
		{"bad-title-utf8", "", string([]byte{0xff}), localImportPlainBody, ""},
		{"bad-parent", "", "导入.md", localImportPlainBody, "folder\x00other"},
		{"parent-too-long", "", "导入.md", localImportPlainBody, strings.Repeat("a", 256)},
		{"empty-body", "", "导入.md", "", ""},
		{"invalid-utf8", "", "导入.md", string([]byte{0xff}), ""},
		{"oversize-body", "", "导入.md", strings.Repeat("a", LocalImportContentLimit+1), ""},
		{"null-body", "", "导入.md", "null", ""},
		{"trailing-json", "", "导入.md", localImportPlainBody + "{}", ""},
		{"missing-root", "", "导入.md", `{}`, ""},
		{"extra-root-key", "", "导入.md", `{"root":{"type":"root","version":1,"children":[]},"untrusted":{}}`, ""},
		{"duplicate-field", "", "导入.md", strings.Replace(localImportPlainBody, `"version":1`, `"version":2,"version":1`, 1), ""},
		{"lone-surrogate", "", "导入.md", strings.Replace(localImportPlainBody, "正文", `\ud800`, 1), ""},
		{"unsupported-node", "", "导入.md", strings.Replace(localImportPlainBody, `"type":"text"`, `"type":"image"`, 1), ""},
		{"leaf-children", "", "导入.md", strings.Replace(localImportPlainBody, `"type":"text"`, `"type":"text","children":[]`, 1), ""},
		{"unknown-property", "", "导入.md", strings.Replace(localImportPlainBody, `"type":"text"`, `"type":"text","onerror":"payload"`, 1), ""},
		{"compound-property", "", "导入.md", strings.Replace(localImportPlainBody, `"type":"text"`, `"type":"text","type version":"payload"`, 1), ""},
		{"wrong-property-type", "", "导入.md", strings.Replace(localImportPlainBody, `"text":"正文 😀 [[literal]]"`, `"text":{}`, 1), ""},
		{"remote-style", "", "导入.md", strings.Replace(localImportPlainBody, `"style":""`, `"style":"background:url(https://example.com)"`, 1), ""},
		{"node-version", "", "导入.md", strings.Replace(localImportPlainBody, `"version":1`, `"version":2`, 1), ""},
		{"nested-root", "", "导入.md", `{"root":{"type":"root","version":1,"children":[{"type":"root","version":1,"children":[]}]}}`, ""},
		{"text-at-root", "", "导入.md", `{"root":{"type":"root","version":1,"children":[{"type":"text","version":1,"text":"orphan"}]}}`, ""},
		{"invalid-heading", "", "导入.md", strings.Replace(localImportRichBody, `"tag":"h1"`, `"tag":"script"`, 1), ""},
		{"giant-indent", "", "导入.md", strings.Replace(localImportPlainBody, `"indent":0`, `"indent":1000000`, 1), ""},
		{"giant-span", "", "导入.md", strings.Replace(localImportRichBody, `"colSpan":1`, `"colSpan":1000000`, 1), ""},
		{"unknown-code-language", "", "导入.md", strings.Replace(localImportRichBody, `"language":"javascript"`, `"language":"unknown-language"`, 1), ""},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			l := researchFixture(t)
			id := tc.id
			if id == "" {
				id = uuid.NewString()
			}
			result, err := l.CreateLocalImport(context.Background(), id, tc.title, tc.body, tc.parent)
			expectImportRejected(t, result, err, id, "invalid-payload")
			importCounts(t, l, 0, 0, 0)
		})
	}
}

func TestLocalImportRichValidationBudgetsAndSafeLinks(t *testing.T) {
	for _, link := range []string{"https://example.com/a?q=1#x", "http://example.com", "mailto:reader@example.com", "tel:+1234", "#anchor", "relative/file.md", "../notes/file.md", "/local/path"} {
		t.Run("safe-"+link, func(t *testing.T) {
			encoded, _ := json.Marshal(link)
			body := strings.Replace(localImportRichBody, `"https://example.com/a"`, string(encoded), 1)
			if err := validateLocalImportPayload("safe.md", body, ""); err != nil {
				t.Fatal(err)
			}
		})
	}
	for _, link := range []string{"javascript:alert(1)", "JaVaScRiPt:alert(1)", "data:text/html,test", "file:///tmp/file", "vbscript:run", "//example.com/path", `\\example.com\path`, "https://example.com\npath", " https://example.com", "https:", "http://user:password@example.com", "mailto:", "tel:", "sms:+1234"} {
		t.Run("unsafe-"+link, func(t *testing.T) {
			encoded, _ := json.Marshal(link)
			body := strings.Replace(localImportRichBody, `"https://example.com/a"`, string(encoded), 1)
			l := researchFixture(t)
			id := uuid.NewString()
			result, err := l.CreateLocalImport(context.Background(), id, "unsafe.md", body, "")
			expectImportRejected(t, result, err, id, "invalid-payload")
			importCounts(t, l, 0, 0, 0)
		})
	}
	t.Run("node-count", func(t *testing.T) {
		body := `{"root":{"type":"root","version":1,"children":[{"type":"paragraph","version":1,"children":[` + strings.Repeat(`{"type":"linebreak","version":1},`, 20000) + `{"type":"linebreak","version":1}]}]}}`
		if len(body) >= LocalImportContentLimit || validateLocalImportPayload("large.md", body, "") == nil {
			t.Fatal("node count bypassed independent byte budget")
		}
	})
	t.Run("depth", func(t *testing.T) {
		body := `{"type":"paragraph","version":1,"children":[]}`
		for i := 0; i < 70; i++ {
			body = `{"type":"quote","version":1,"shadowRoot":true,"children":[` + body + `]}`
		}
		body = `{"root":{"type":"root","version":1,"children":[` + body + `]}}`
		if validateLocalImportPayload("deep.md", body, "") == nil {
			t.Fatal("deep structure was accepted")
		}
	})
	t.Run("expanded-table", func(t *testing.T) {
		body := strings.ReplaceAll(strings.ReplaceAll(localImportRichBody, `"colSpan":1`, `"colSpan":100`), `"rowSpan":1`, `"rowSpan":100`)
		if validateLocalImportPayload("wide.md", body, "") == nil {
			t.Fatal("expanded table bypassed node budget")
		}
	})
}

func TestLocalImportPermittedBoundaryAndSupplementalRegisteredNodes(t *testing.T) {
	if err := validateLocalImportPayload(strings.Repeat("😀", 255), localImportPlainBody, ""); err != nil {
		t.Fatal("255 Unicode rune title rejected", err)
	}
	paired := strings.Replace(localImportPlainBody, "😀", `\ud83d\ude00`, 1)
	if err := validateLocalImportPayload("unicode.md", paired, ""); err != nil {
		t.Fatal("valid surrogate pair rejected", err)
	}
	body := `{"root":{"type":"root","version":1,"children":[{"type":"code","version":1,"language":"javascript","children":[{"type":"code-highlight","version":1,"text":"const","highlightType":"keyword","detail":0,"format":0,"mode":"normal","style":""},{"type":"tab","version":1,"text":"\t","detail":0,"format":0,"mode":"normal","style":""},{"type":"linebreak","version":1}]},{"type":"paragraph","version":1,"children":[{"type":"autolink","version":1,"url":"https://example.com","isUnlinked":false,"children":[{"type":"text","version":1,"text":"example"}]}]}]}}`
	if err := validateLocalImportPayload("supplement.md", body, ""); err != nil {
		t.Fatal(err)
	}
	base := strings.Replace(localImportPlainBody, "正文 😀 [[literal]]", "", 1)
	exact := strings.Replace(base, `"text":""`, `"text":"`+strings.Repeat("a", LocalImportContentLimit-len(base))+`"`, 1)
	if len(exact) != LocalImportContentLimit || validateLocalImportPayload("boundary.md", exact, "") != nil {
		t.Fatal("exact 2 MiB valid document was rejected")
	}
}

func TestLocalImportDatabaseAndContextErrorsRemainUnknown(t *testing.T) {
	for _, scenario := range []string{"cancelled", "closed-db", "folder-scan-failure", "trigger-claims-folder-rejection"} {
		t.Run(scenario, func(t *testing.T) {
			l := researchFixture(t)
			ctx := context.Background()
			parent := ""
			switch scenario {
			case "cancelled":
				var cancel context.CancelFunc
				ctx, cancel = context.WithCancel(ctx)
				cancel()
			case "closed-db":
				l.FileDAO.DB.Close()
			case "folder-scan-failure":
				parent = uuid.NewString()
				importFolder(t, l, parent, "", 1, 0)
				if _, err := l.FileDAO.DB.Exec(`UPDATE files SET is_folder='not a boolean' WHERE id=?`, parent); err != nil {
					t.Fatal(err)
				}
			case "trigger-claims-folder-rejection":
				if _, err := l.FileDAO.DB.Exec(`CREATE TRIGGER reject_import BEFORE INSERT ON files BEGIN SELECT RAISE(ABORT,'目标目录或上级目录不可用，未创建'); END`); err != nil {
					t.Fatal(err)
				}
			}
			result, err := l.CreateLocalImport(ctx, uuid.NewString(), "unknown.md", localImportPlainBody, parent)
			var typed *dao.ResearchPrecommitError
			if err == nil || result != nil || errors.As(err, &typed) {
				t.Fatalf("unknown result was misclassified: %+v %v", result, err)
			}
			if scenario != "closed-db" {
				files := 0
				if scenario == "folder-scan-failure" {
					files = 1
				}
				importCounts(t, l, files, 0, 0)
			}
		})
	}
}

func TestLocalImportIndexFailureRollsBackReceiptAndAllowsSameIDRetry(t *testing.T) {
	l := researchFixture(t)
	if _, err := l.FileDAO.DB.Exec(`CREATE TRIGGER failed_index AFTER INSERT ON files BEGIN SELECT RAISE(ABORT,'synthetic index unavailable'); END`); err != nil {
		t.Fatal(err)
	}
	id := uuid.NewString()
	result, err := l.CreateLocalImport(context.Background(), id, "retry.md", localImportPlainBody, "")
	if err == nil || result != nil {
		t.Fatal("index database failure must remain unknown", result, err)
	}
	importCounts(t, l, 0, 0, 0)
	if _, err := l.FileDAO.DB.Exec(`DROP TRIGGER failed_index`); err != nil {
		t.Fatal(err)
	}
	result, err = l.CreateLocalImport(context.Background(), id, "retry.md", localImportPlainBody, "")
	if err != nil || result.Status != "committed" {
		t.Fatal(result, err)
	}
	importCounts(t, l, 1, 1, 0)
}

func TestLocalImportConcurrentSameRequestCreatesOnce(t *testing.T) {
	l := researchFixture(t)
	id := uuid.NewString()
	var wg sync.WaitGroup
	errors := make(chan error, 12)
	identities := make(chan string, 12)
	for i := 0; i < 12; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			result, err := l.CreateLocalImport(context.Background(), id, "concurrent.md", localImportPlainBody, "")
			if err != nil || result == nil || result.Status != "committed" || result.Receipt == nil {
				errors <- fmt.Errorf("result=%+v err=%v", result, err)
				return
			}
			identities <- result.Receipt.FileID
		}()
	}
	wg.Wait()
	close(errors)
	close(identities)
	for err := range errors {
		t.Error(err)
	}
	first := ""
	for id := range identities {
		if first == "" {
			first = id
		} else if id != first {
			t.Error("same task produced distinct identities")
		}
	}
	importCounts(t, l, 1, 1, 0)
}

