func TestLocalImportDecodeRejectsAmbiguousRequests(t *testing.T) {
	for _, body := range []string{
		`null`, `[]`, `{}`, `{"title":"a","content":"b"}`,
		`{"title":"a","content":"b","parent_id":"","extra":1}`,
		`{"title":"a","content":"b","parent_id":"","title":"c"}`,
		`{"title":null,"content":"b","parent_id":""}`,
		`{"title":"a","content":"b","parent_id":""}{}`,
		`{"title":"\ud800","content":"b","parent_id":""}`,
	} {
		if _, err := DecodeLocalImportInput([]byte(body)); err == nil {
			t.Errorf("accepted ambiguous request: %s", body)
		}
	}
	input := LocalImportInput{Title: "正确.md", Content: localImportRichBody, ParentID: ""}
	encoded, _ := json.Marshal(input)
	decoded, err := DecodeLocalImportInput(encoded)
	if err != nil || *decoded != input {
		t.Fatal(decoded, err)
	}
}
